    int maxValue = 26 * n;            // all 'z's
    if (k < minValue || k > maxValue) {
        throw new IllegalArgumentException("k is out of valid range for given n");
    }

    char[] result = new char[n];
    // Start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - minValue;     // extra value to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // can increase at most 25 per char
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

