public static int squarePermutations(int[] A) {
    int n=A.length;
    if(n==0) return 0; // maybe return 0? but empty array maybe 0 permutations? However problem didn't mention. We'll return 0.

    Arrays.sort(A);
    List<List<Integer>> neighbors= new ArrayList<>();
    for(int i=0;i<n;i++){
        List<Integer> list= new ArrayList<>();
        for(int j=0;j<n;j++){
            if(i==j) continue;
            int sum=A[i]+A[j];
            int s=(int)Math.sqrt(sum);
            if(s*s==sum) list.add(j);
        }
        neighbors.add(list);
    }

    int size=1<<n;
    int[][] memo=new int[size][n];
    for(int i=0;i<size;i++){
        Arrays.fill(memo[i], -1);
    }

    int fullMask = size-1;
    // lambda recursive
    java.util.function.BiFunction<Integer,Integer,Integer> dfs = new java.util.function.BiFunction<Integer,Integer,Integer>() {
        @Override
        public Integer apply(Integer mask, Integer last){
            if(mask==fullMask) return 1;
            int memoVal = memo[mask][last];
            if(memoVal!=-1) return memoVal;
            int count=0;
            for(int next: neighbors.get(last)){
                if((mask & (1<<next))!=0) continue;
                if(next>0 && A[next]==A[next-1] && (mask & (1<<(next-1)))==0) continue;
                count += apply(mask | (1<<next), next);
            }
            memo[mask][last]=count;
            return count;
        }
    };

    int total=0;
    for(int i=0;i<n;i++){
        if(i>0 && A[i]==A[i-1]) continue; // skip duplicate start
        total += dfs.apply(1<<i, i);
    }
    return total;
}

